WITH enriched AS (SELECT *, ROW_NUMBER() OVER (ORDER BY started_at, id) AS event_seq, LAST_VALUE(browser, TRUE) OVER (PARTITION BY country, customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_browser, ROW_NUMBER() OVER w_running AS event_seq_2, FIRST_VALUE(browser) IGNORE NULLS OVER w_hist AS first_known_browser FROM sessions WINDOW w_running AS (PARTITION BY device ORDER BY started_at, id), w_hist AS (PARTITION BY browser ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT CASE WHEN event_seq_2 >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END AS event_seq_2_tier, MAX(event_seq) FILTER (WHERE country = 'UK') AS uk_max_event_seq, COUNT(DISTINCT browser) AS distinct_browsers, COUNT(CASE WHEN device = 'mobile' THEN 1 END) AS mobile_count, COUNT(DISTINCT id) AS distinct_ids, MIN(started_at) AS first_started_at, MAX(started_at) AS last_started_at FROM enriched GROUP BY CASE WHEN event_seq_2 >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING distinct_ids >= 1;
